WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pc_ga_uneven'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '不均匀分组', 'kp-pc-ga-uneven', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "可为空的隔板法"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不仅每人分到的可以不一样，甚至有人可以分到 0 个！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“将 10 个相同的苹果分给 3 个小朋友，【可以有人一个都分不到】，有几种分法？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心战法：借壳生蛋"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "既然可以分 0 个，那我就找每个小朋友“借”一个苹果。现在苹果总数变成了 10 + 3 = 13 个。然后规定：现在每个人至少分 1 个！"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "此时分出来的结果，把刚才借的拿走，刚好对应有人可以为 0 的情况。"}]}, {"type": "katexBlock", "attrs": {"content": "N = C_{n+m-1}^{m-1} = C_{10+3-1}^{3-1} = C_{12}^2 = 66"}}]}$$ AS jsonb), NULL, '不均匀分组的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "不均匀分组"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_ga_uneven", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
